insert into public.levels(code,title_fa,title_en,description,sort_order) values
('A1','مبتدی','Beginner','برای شروع: یک کتاب اصلی، شنیدنِ قابل‌فهم و تمرین‌های پایه. اول مسیر اصلی را دنبال کن و بعد فقط برای مهارتی که نیاز داری منبع تکمیلی باز کن.',1),
('A2','پایه','Elementary','برای تثبیت پایه‌ها و افزایش دامنه‌ی واژگان و مکالمه. کتاب اصلی را محور نگه دار و تمرین شنیداری و آزمون را به آن اضافه کن.',2),
('B1','میانی','Intermediate','برای رسیدن به استقلال زبانی: متن و خبر ساده‌تر، شنیدار واقعی‌تر و تمرین منظم چهار مهارت.',3),
('B2','میانی رو به بالا','Upper Intermediate','برای درک زبان طبیعی‌تر، موضوعات پیچیده‌تر و آمادگی آزمون. منابع کمتر اما عمیق‌تر انتخاب شده‌اند.',4),
('C1','پیشرفته','Advanced','برای دقت، دامنه‌ی زبانی و درک محتوای اصیل. تمرکز روی زبان واقعی، واژگان پیشرفته و تولید دقیق‌تر زبان است.',5),
('C2','تسلط','Proficient','برای پالایش زبان و تسلط بر ظرافت‌ها. در این سطح کیفیت و عمق منبع از تعداد منابع مهم‌تر است.',6)
