-- German Library v7 curated seed
-- Official/public URLs only; private/licensed files should be uploaded from Admin.

on conflict(code) do update set title_fa=excluded.title_fa,title_en=excluded.title_en,description=excluded.description,sort_order=excluded.sort_order;

on conflict(id) do update set collection=excluded.collection,level_code=excluded.level_code,title=excluded.title,description=excluded.description,is_core=excluded.is_core,order_index=excluded.order_index,status=excluded.status;

on conflict(id) do update set collection=excluded.collection,level_code=excluded.level_code,course_id=excluded.course_id,title=excluded.title,description=excluded.description,type=excluded.type,skill=excluded.skill,priority=excluded.priority,provider=excluded.provider,source_url=excluded.source_url,source_storage_path=excluded.source_storage_path,pricing=excluded.pricing,featured=excluded.featured,duration_minutes=excluded.duration_minutes,link_status=excluded.link_status,verified_at=excluded.verified_at,order_index=excluded.order_index,status=excluded.status;
